"""Database model for use by SQLAlchemy."""

import json
import re
from functools import cached_property
from typing import List, Optional

from aksharamukha import transliterate
from sqlalchemy import DateTime, ForeignKey, and_, case, null, or_
from sqlalchemy import Column, Integer

from sqlalchemy.ext.hybrid import hybrid_property
from sqlalchemy.orm import (
    DeclarativeBase,
    Mapped,
    foreign,
    mapped_column,
    object_session,
    relationship,
)
from sqlalchemy.orm import declared_attr

from sqlalchemy.sql import func

from tools.pali_sort_key import pali_sort_key
from tools.pos import CONJUGATIONS, DECLENSIONS, EXCLUDE_FROM_FREQ
from tools.clean_machine import clean_machine

from tools.sbs_table_functions import SBS_table_tools, paragraphs_are_similar
from tools.configger import config_read


class Base(DeclarativeBase):
    pass


