    # Determine uniqueness of ru_notes
    @cached_property
    def needs_ru_notes(self) -> bool:
        if self.ru and self.ru.ru_notes:
            if not self.notes:
                return True
            if paragraphs_are_similar(self.ru.ru_notes, self.notes, 0.999):
                return False
            return True
        return False

