        tpr_codes = load_tpr_codes_set()

        if self.dpd_code:
            code = self.dpd_code.lower().strip()
            if code in tpr_codes:
                return True
            # Handle cases like an5.31.1 -> an5.31
            if "." in code:
                base_code = code.split(".")[0]
                if base_code in tpr_codes:
                    return True
        return False

