    @cached_property
    def sc_eng_link(self) -> str | None:
        if self.sc_code:
            return f"https://suttacentral.net/{self.sc_code}/en/sujato"
        else:
            return None

    @cached_property
    def has_tpr(self) -> bool:
        from tools.cache_load import load_tpr_codes_set

        tpr_codes = load_tpr_codes_set()

        if self.dpd_code:
            code = self.dpd_code.lower().strip()
            if code in tpr_codes:
                return True
            # Handle cases like an5.31.1 -> an5.31
            if "." in code:
                base_code = code.split(".")[0]
                if base_code in tpr_codes:
                    return True
        return False

    @cached_property
    def sc_book_code(self) -> str | None:
        if self.sc_code:
            return re.sub(r"\d+\.*-*\d*", "", self.sc_code)
        else:
            return None

    @cached_property
    def sc_github(self) -> str | None:
        if self.sc_code:
            return (
