function loadFontSize() {
  fontSize = localStorage.getItem("fontSize");
  if (fontSize === null) {
    bodyStyle = window.getComputedStyle(document.body);
    fontSize = parseInt(bodyStyle.getPropertyValue("font-size"), 10);
  } else {
