#!/usr/bin/env python3

import json
import subprocess
from pathlib import Path

def get_modified_files(command):
    result = subprocess.run(command, shell=True, capture_output=True, text=True)
    return set(filter(None, result.stdout.split('\n')))

def check_shadows():
    registry_path = "conductor/templates/upstream_sync_rehearsal/dps_sync_registry.json"
    with open(registry_path, "r") as f:
        registry = json.load(f)

    # Files modified in the sync commit
    upstream_modified = get_modified_files("git diff HEAD^ HEAD --name-only")

    # Files modified manually (uncommitted)
    local_modified = get_modified_files("git diff HEAD --name-only")

    copies = []
    if "russian_copies" in registry:
        for shadow, source in registry["russian_copies"].items():
            copies.append((shadow, source))
    if "sbs_copies" in registry:
        for shadow, source in registry["sbs_copies"].items():
            copies.append((shadow, source))

    unmodified_shadows = []

    for shadow, source in copies:
        # Check if source was modified in the sync commit
        source_was_modified = False
        if source.endswith('/'):
            for uf in upstream_modified:
                if uf.startswith(source):
                    source_was_modified = True
                    break
        else:
            if source in upstream_modified:
                source_was_modified = True

        if source_was_modified:
            # Check if the shadow was modified locally
            shadow_is_modified = False
            if shadow.endswith('/'):
                for lf in local_modified:
                    if lf.startswith(shadow):
                        shadow_is_modified = True
                        break
            else:
                if shadow in local_modified:
                    shadow_is_modified = True

            if not shadow_is_modified:
                unmodified_shadows.append((source, shadow))

    if unmodified_shadows:
        print("WARNING: The following upstream sources were modified in the sync commit, but their shadow copies have NOT been modified locally:")
        for source, shadow in unmodified_shadows:
            print(f"  Source: {source}  =>  Shadow: {shadow}")
        exit(1)
    else:
        print("SUCCESS: All shadow copies of modified upstream sources have been updated.")
        exit(0)

if __name__ == "__main__":
    check_shadows()

