        cl.{{ d.sbs_class_anki }} 
    {% endif %}
    {% if d.needs_class_example %}
        {{ d.class_source }} {{ d.class_sutta }}
    </p>
    {% endif %}

    {% if d.needs_discourses_example %}
        <p>{{ d.discourses_example }}</p>
        <p class="sutta">
            {{ d.discourses_source }} {{ d.discourses_sutta }}
