{{ d.header }}
<body>
<div class="dpd">
    <p>
        {{ d.ru_pos }}. 
        {% if d.ru_plus_case %}
        ({{ d.ru_plus_case }}) 
        {% endif %}
        {% if d.ru_is_ai_translation %}
