        {% endif %}
        {{ d.ru_meaning }} 
        {% if d.ru_summary %}
        [{{ d.ru_summary }}] 
        {% endif %}
        {{ d.ru_complete }} 
        {% if d.show_id %}
        <span class="gray">{{ d.i.id }}</span>
        {% endif %}
    </p>
</div>
<div class="button-box">
    {% if d.i.needs_audio_button %}
    <a class="dpd-button play" onclick="playAudio('{{ d.i.lemma_clean }}', this)" title="Прослушать"><svg viewBox="0 0 24 24" width="16px" height="16px" fill="currentColor" stroke="currentColor" stroke-width="0"><path d="M8 5v14l11-7z"></path></svg></a>
    {% endif %}
    {% if d.i.needs_sutta_info_button %}
    <a class="dpd-button" href="#" data-target="ru_sutta_info_{{ d.i.lemma_1_ }}">сутта</a>
    {% endif %}
    {% if d.i.needs_grammar_button %}
    <a class="dpd-button" href="#" data-target="ru_grammar_{{ d.i.lemma_1_ }}">грамматика</a>
    {% endif %}
    {% if d.i.needs_example_button %}
    <a class="dpd-button" href="#" data-target="ru_example_{{ d.i.lemma_1_ }}">пример</a>
    {% endif %}
    {% if d.i.needs_examples_button %}
    <a class="dpd-button" href="#" data-target="ru_examples_{{ d.i.lemma_1_ }}">примеры</a>
    {% endif %}
    {% if d.i.needs_conjugation_button %}
    <a class="dpd-button" href="#" data-target="ru_conjugation_{{ d.i.lemma_1_ }}">спряжения</a>
    {% endif %}
    {% if d.i.needs_declension_button %}
    <a class="dpd-button" href="#" data-target="ru_declension_{{ d.i.lemma_1_ }}">склонения</a>
    {% endif %}
    {% if d.i.needs_root_family_button %}
    <a class="dpd-button" href="#" data-target="ru_family_root_{{ d.i.lemma_1_ }}">семья корня</a>
    {% endif %}
    {% if d.i.needs_word_family_button %}
    <a class="dpd-button" href="#" data-target="ru_family_word_{{ d.i.lemma_1_ }}">семья слова</a>
    {% endif %}
    {% if d.i.needs_compound_family_button %}
    <a class="dpd-button" href="#" data-target="ru_family_compound_{{ d.i.lemma_1_ }}">семья составного</a>
    {% elif d.i.needs_compound_families_button %}
    <a class="dpd-button" href="#" data-target="ru_family_compound_{{ d.i.lemma_1_ }}">семья составных</a>
    {% endif %}
    {% if d.i.needs_idioms_button %}
    <a class="dpd-button" href="#" data-target="ru_family_idiom_{{ d.i.lemma_1_ }}">идиомы</a>
    {% endif %}
    {% if d.i.needs_set_button %}
    <a class="dpd-button" href="#" data-target="ru_family_set_{{ d.i.lemma_1_ }}">группа</a>
    {% elif d.i.needs_sets_button %}
    <a class="dpd-button" href="#" data-target="ru_family_set_{{ d.i.lemma_1_ }}">группы</a>
    {% endif %}
    {% if d.i.needs_frequency_button %}
    <a class="dpd-button" href="#" data-target="ru_frequency_{{ d.i.lemma_1_ }}">частота</a>
    {% endif %}
    <a class="dpd-button" href="#" data-target="ru_feedback_{{ d.i.lemma_1_ }}">о словаре</a>
</div>

{% if d.i.needs_sutta_info_button %}
<div id="ru_sutta_info_{{ d.i.lemma_1_ }}" name="sutta-info-div" class="dpd content hidden">
    {{ d.jinja_env.get_template("dpd_sutta_info_ru.jinja").render(d=d) }}
</div>
{% endif %}

{% if d.i.needs_grammar_button %}
<div id="ru_grammar_{{ d.i.lemma_1_ }}" class="dpd content hidden">
    {{ d.jinja_env.get_template("dpd_grammar_ru.jinja").render(d=d) }}
</div>
{% endif %}

{% if d.i.needs_example_button or d.i.needs_examples_button %}
<div id="{% if d.i.needs_examples_button %}ru_examples_{{ d.i.lemma_1_ }}{% else %}ru_example_{{ d.i.lemma_1_ }}{% endif %}" class="dpd content hidden">
    {{ d.jinja_env.get_template("dpd_example_ru.jinja").render(d=d) }}
</div>
{% endif %}

{% if d.i.needs_conjugation_button or d.i.needs_declension_button %}
<div id="{% if d.i.needs_declension_button %}ru_declension_{{ d.i.lemma_1_ }}{% else %}ru_conjugation_{{ d.i.lemma_1_ }}{% endif %}" class="dpd content hidden">
    {{ d.jinja_env.get_template("dpd_inflection_ru.jinja").render(d=d) }}
</div>
