resultDisplay.originalContent:
{{ d.header }}
<body>
<div class="dpd">
    <p>
        {% if d.sbs and d.sbs.class_anki %}
        <a class="link" href="{{ d.sbs_class_link }}">
            <i>(cl.{{ d.sbs.class_anki }}{{ '*' if d.sbs.class_extra else '' }})</i>
        </a>
        <span class="gray"> | </span>
        {% endif %}

        {{ d.i.pos }}. 
        {% if d.i.plus_case %}
        ({{ d.i.plus_case }}) 
        {% endif %}

        {% if d.su and d.su.tbw %}
        <a class="link" href="{{ d.su.tbw }}">{{ d.meaning_combo_html }}</a>
        {% else %}
        {{ d.meaning_combo_html }}
        {% endif %}

        {% if d.i.construction_summary %}
        [{{ d.i.construction_summary }}] 
        {% endif %}

        {{ d.i.degree_of_completion_html }} 
        {% if d.show_id %}
        <span class="gray">{{ d.i.id }}</span>
        {% endif %}
    </p>
</div>
<div class="button-box">
    {% if d.i.needs_audio_button %}
    <a class="dpd-button play" onclick="playAudio('{{ d.i.lemma_clean }}', this)" title="Play Audio"><svg viewBox="0 0 24 24" width="16px" height="16px" fill="currentColor" stroke="currentColor" stroke-width="0"><path d="M8 5v14l11-7z"></path></svg></a>
    {% endif %}
    {% if d.i.needs_sutta_info_button %}
    <a class="dpd-button" href="#" data-target="sutta_info_{{ d.i.lemma_1_ }}">sutta</a>
    {% endif %}
    {% if d.i.needs_grammar_button %}
    <a class="dpd-button" href="#" data-target="grammar_{{ d.i.lemma_1_ }}">grammar</a>
    {% endif %}
    {% if d.needs_sbs_example_button %}
    <a class="dpd-button" href="#" data-target="sbs_example_{{ d.i.lemma_1_ }}">sbs</a>
    {% endif %}
    {% if d.i.needs_example_button %}
    <a class="dpd-button" href="#" data-target="example_{{ d.i.lemma_1_ }}">example</a>
    {% endif %}
    {% if d.i.needs_examples_button %}
    <a class="dpd-button" href="#" data-target="examples_{{ d.i.lemma_1_ }}">examples</a>
    {% endif %}
    {% if d.i.needs_conjugation_button %}
    <a class="dpd-button" href="#" data-target="conjugation_{{ d.i.lemma_1_ }}">conjugation</a>
    {% endif %}
    {% if d.i.needs_declension_button %}
    <a class="dpd-button" href="#" data-target="declension_{{ d.i.lemma_1_ }}">declension</a>
    {% endif %}
    {% if d.i.needs_root_family_button %}
    <a class="dpd-button" href="#" data-target="family_root_{{ d.i.lemma_1_ }}">root family</a>
    {% endif %}
    {% if d.i.needs_word_family_button %}
    <a class="dpd-button" href="#" data-target="family_word_{{ d.i.lemma_1_ }}">word family</a>
    {% endif %}
    {% if d.i.needs_compound_family_button %}
    <a class="dpd-button" href="#" data-target="family_compound_{{ d.i.lemma_1_ }}">compound family</a>
    {% elif d.i.needs_compound_families_button %}
    <a class="dpd-button" href="#" data-target="family_compound_{{ d.i.lemma_1_ }}">compound families</a>
    {% endif %}
    {% if d.i.needs_idioms_button %}
    <a class="dpd-button" href="#" data-target="family_idiom_{{ d.i.lemma_1_ }}">idioms</a>
    {% endif %}
    {% if d.i.needs_set_button %}
    <a class="dpd-button" href="#" data-target="family_set_{{ d.i.lemma_1_ }}">set</a>
    {% elif d.i.needs_sets_button %}
    <a class="dpd-button" href="#" data-target="family_set_{{ d.i.lemma_1_ }}">sets</a>
    {% endif %}
    {% if d.i.needs_frequency_button %}
    <a class="dpd-button" href="#" data-target="frequency_{{ d.i.lemma_1_ }}">frequency</a>
    {% endif %}
    <a class="dpd-button" href="#" data-target="feedback_{{ d.i.lemma_1_ }}">feedback</a>
</div>

{% if d.i.needs_sutta_info_button %}
<div id="sutta_info_{{ d.i.lemma_1_ }}" name="sutta-info-div"
    class="dpd content hidden">
    <table class="sutta-info">

        <!-- CST -->

        {% if d.su.cst_code %}
        <tr>
            <th class="heading top" colspan="2">
                Chaṭṭha Saṅgāyana Tipiṭaka (CST)
            </th>
        </tr>
        {% endif %}

        {% if d.su.cst_code %}
        <tr>
            <th>
                CST Code
            </th>
            <td>
                {{ d.su.cst_code }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_nikaya %}
        <tr>
            <th>
                Nikāya
            </th>
            <td>
                {{ d.su.cst_nikaya }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_book %}
        <tr>
            <th>
                Book
            </th>
            <td>
                {{ d.su.cst_book }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_section %}
        <tr>
            <th>
                Section
            </th>
            <td>
                {{ d.su.cst_section }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_vagga %}
        <tr>
            <th>
                Vagga
            </th>
            <td>
                {{ d.su.cst_vagga }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_sutta %}
        <tr>
            <th>
                Sutta
            </th>
            <td>
                {{ d.su.cst_sutta }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_paranum %}
        <tr>
            <th>
                Paragraph
            </th>
            <td>
                {{ d.su.cst_paranum }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_file %}
        <tr>
            <th>
                File
            </th>
            <td>
                {{ d.su.cst_file }}
            </td>

        </tr>
        <tr>
            <th>
                GitHub
            </th>
            <td>
                <a href="https://github.com/VipassanaTech/tipitaka-xml/tree/main/{{ d.su.cst_file }}" target="_blank">{{
                    d.su.cst_file }}</a>

            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_code %}
        <tr>
            <th class="heading" colspan="2">
                Apps & Websites using CST
            </th>
        </tr>
        {% endif %}

        {% if d.su.dpr_link %}
        <tr>
            <th>
                Digital Pali Reader
            </th>
            <td>
                <a href="{{ d.su.dpr_link }}" target="_blank">{{ d.su.dpr_link }}</a>
            </td>
        </tr>
        {% endif %}

        {% if d.su.has_tpr %}
        <tr>
            <th>
                Tipiṭaka Pāḷi Reader
            </th>
            <td>
                <a href="https://tpr.pali.tools/open/?sutta={{ d.su.dpd_code.lower() }}" target="_blank">https://tpr.pali.tools/open/?sutta={{ d.su.dpd_code.lower() }}</a>
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_code %}
        <tr>
            <th>
                TipitakaPali.org
            </th>
            <td>
                <a href="{{ d.su.tpp_org }}" target="_blank">{{ d.su.tpp_org }}</a>
            </td>
        </tr>
        {% endif %}

        <!-- page numbers -->

        {% if d.su.cst_m_page %}
        <tr>
            <th class="heading" colspan="2">
                CST Page Numbers in Printed Editions
            </th>
        </tr>
        {% endif %}

        {% if d.su.cst_m_page %}
        <tr>
            <th>
                Myanmar
            </th>
            <td>
                {{ d.su.cst_m_page }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_t_page %}
        <tr>
            <th>
                Thai
            </th>
            <td>
                {{ d.su.cst_t_page }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_v_page %}
        <tr>
            <th>
                VRI
            </th>
            <td>
                {{ d.su.cst_v_page }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.cst_p_page %}
        <tr>
            <th>
                PTS
            </th>
            <td>
                {{ d.su.cst_p_page }}
            </td>
        </tr>
        {% endif %}

        <!-- sutta central -->

        {% if d.su.sc_code %}
        <tr>
            <th class="heading" colspan="2">
                Sutta Central
            </th>
        </tr>
        {% endif %}

        {% if d.su.sc_code %}
        <tr>
            <th>
                SC Code
            </th>
            <td>
                {{ d.su.sc_code }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_book %}
        <tr>
            <th>
                Book
            </th>
            <td>
                {{ d.su.sc_book }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_vagga %}
        <tr>
            <th>
                Vagga
            </th>
            <td>
                {{ d.su.sc_vagga }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_sutta %}
        <tr>
            <th>
                Sutta
            </th>
            <td>
                {{ d.su.sc_sutta }}
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_eng_sutta %}
        <tr>
            <th>
                Title
            </th>
            <td>
                <i>{{ d.su.sc_eng_sutta }}</i>
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_blurb %}
        <tr>
            <th>
                Blurb
            </th>
            <td>
                <i>{{ d.su.sc_blurb }}</i>
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_card_link %}
        <tr>
            <th>
                Links
            </th>
            <td>
                {% if d.su.sc_code %}
                <a href="{{ d.su.sc_card_link }}" target="_blank">Sutta
                    Card</a>,
                <a href="{{ d.su.sc_pali_link }}" target="_blank">Pāḷi Text</a>,
                <a href="{{ d.su.sc_eng_link }}" target="_blank">English
                    Translation</a>
                {% endif %}
            </td>
        </tr>
        {% endif %}

        {% if d.su.sc_file_path %}
        <tr>
            <th>
                File
            </th>
            <td>
                {{ d.su.sc_file_path }}
            </td>
        </tr>
        <tr>
            <th>
                GitHub
            </th>
            <td>
                <a href="{{ d.su.sc_github }}" target="_blank">{{
                    d.su.sc_file_path }}</a>
            </td>
        </tr>
        {% endif %}

        <!-- websites -->

        {% if d.su.sc_code %}
        <tr>
            <th class="heading" colspan="2">
                Websites using Sutta Central
            </th>
        </tr>
        {% endif %}

        {% if d.su.tbw %}
        <tr>
            <th>
                The Buddha's Words
            </th>
            <td>
                <a href="{{ d.su.tbw }}" target="_blank">{{ d.su.tbw }}</a>
            </td>
        </tr>
        {% endif %}

        {% if d.su.tbw_legacy %}
        <tr>
            <th>
                TBW Legacy
            </th>
            <td>
