document.addEventListener("click", function (event) {
    var target = event.target;
    const classNames = ["button", "dpd-button"]
    if (classNames.some(className => target.classList.contains(className))) {
        ru_button_click(target);
        event.preventDefault();
    }
});

function ru_button_click(el) {
    const target_id = el.getAttribute("data-target");
    var target = document.getElementById(target_id);

    if (target) {
        if (target.textContent.includes("загружается...")) {
            ru_loadData()
        };

        target.classList.toggle("hidden");
        if (el.classList.contains("close")) {
            var target_control = document.querySelector('a.button[data-target="' + target_id + '"]');
            if (!target_control) {
                target_control = document.querySelector('a.dpd-button[data-target="' + target_id + '"]');
            }
            if (target_control) {
                target_control.classList.toggle("active");
            }
        } else {
            el.classList.toggle("active");
        }
    }
};

document.addEventListener('DOMContentLoaded', function () {
    ru_loadData()
});

function ru_loadData() {
    var metaTags = document.querySelectorAll("meta[data_key]");
    var metaArray = Array.from(metaTags);
    metaArray.forEach(tag => {
        var dataKey = tag.getAttribute("data_key");
        var data = window[dataKey];
        if (dataKey.startsWith("rudata_")) {
            ru_loadButtonContent(data)
        } else if (dataKey.startsWith("rootdata_ru_")) {
            ru_loadRootButtonContent(data)
        }
    });
};

//// load json data into buttons 

function ru_loadButtonContent(data) {
    const lemmaTag = data.lemma.replace(/ /g, "_").replace(".", "_") // a 1.1 > a_1_1

    //// feedback

    const feedbackHTML = ru_makeFeedback(data);
    const feedbackElement = document.getElementById(`ru_feedback_${lemmaTag}`)
    if (feedbackElement) feedbackElement.innerHTML = feedbackHTML

    // frequency

    if (data.CstFreq != undefined) {
        const frequencyHTML = ru_makeFrequency(data);
        const frequencyElement = document.getElementById(`ru_frequency_${lemmaTag}`)
        if (frequencyElement) frequencyElement.innerHTML = frequencyElement.innerHTML.replace("частота загружается...", frequencyHTML)
    };

    //// family compounds

    if (
        data.family_compounds
        && data.family_compounds.length > 0
        && typeof ru_family_compound_json !== "undefined"
    ) {
        const familyCompoundHtml = ru_makeFamilyCompoundHtml(data)
        const familyCompoundElement = document.getElementById(`ru_family_compound_${lemmaTag}`)
        if (familyCompoundElement) familyCompoundElement.innerHTML = familyCompoundHtml
    };

    //// family root

    if (data.family_root != ""
        && typeof ru_family_root_json !== "undefined"
    ) {
        const fr = ru_family_root_json[data.family_root];
        const familyRootHtml = ru_makeFamilyRootHtml(fr, data, "lemma");
        const familyRootElement = document.getElementById(`ru_family_root_${lemmaTag}`);
        if (familyRootElement) familyRootElement.innerHTML = familyRootHtml;
    };

    //// family idioms

    if (
        data.family_idioms
        && data.family_idioms.length > 0
        && typeof ru_family_idiom_json !== "undefined"
    ) {
        const familyIdiomHtml = ru_makeFamilyIdioms(data)
        const familyIdiomElement = document.getElementById(`ru_family_idiom_${lemmaTag}`)
        if (familyIdiomElement) familyIdiomElement.innerHTML = familyIdiomHtml
    };

    //// family sets

    if (
        data.family_sets
        && data.family_sets.length > 0
        && typeof ru_family_set_json !== "undefined"
    ) {
        const familySetHtml = ru_makeFamilySets(data)
        const familySetElement = document.getElementById(`ru_family_set_${lemmaTag}`)
        if (familySetElement) familySetElement.innerHTML = familySetHtml
    };

    //// family word

    if (
        data.family_word
        && typeof ru_family_word_json !== "undefined"
    ) {
        const familyWordHtml = ru_makeFamilyWordHtml(data);
        const familyWordElement = document.getElementById(`ru_family_word_${lemmaTag}`)
        if (familyWordElement) familyWordElement.innerHTML = familyWordHtml
    };
};

function ru_loadRootButtonContent(data) {
    const familyRootDivs = document.querySelectorAll('div[id^="ru_family_root_"]');
    var familyRootArray = Array.from(familyRootDivs);
    familyRootArray.forEach(item => {
        const key_id = item.id
