      itemTag = item.replace(/ /g, "_");
      html += `<a class="jump" href="#${lemmaTag}_idiom_${itemTag}">${item}</a> `;
    });
    html += `</p>`;
  }

  familyIdiomList.forEach((item) => {
    fi = family_idiom_json[item];
    itemTag = item.replace(/ /g, "_");

    if (familyIdiomList.length > 1) {
