    const familyWordHtml = sbs_makeFamilyWordHtml(data);
    const familyWordElement = document.getElementById(
      `family_word_${lemmaTag}`
    );
    if (familyWordElement) familyWordElement.innerHTML = familyWordHtml;
  }
}

