                <th><a class="link" href="https://docs.google.com/forms/d/1iMD9sCSWFfJAFCFYuG9HRIyrr9KFRy0nAOVApM998wM/viewform?usp=pp_url&entry.438735500={{ d.i.lemma_link }}&entry.326955045=Перевод&entry.1433863141=GoldenDict+{{ d.today }}" target="_blank">Перевод ИИ</a></th>
