        </tr>
        {% endif %}

        {% if d.i.synonym %}
        <tr>
            <th>Synonym</th>
            <td>{{ d.i.synonym }}</td>
        </tr>
        {% endif %}

        {% if d.i.variant %}
        <tr>
            <th>Variant</th>
            <td>{{ d.i.variant }}</td>
        </tr>
        {% endif %}

        {% if d.i.commentary and d.i.commentary != "-" %}
        <tr>
