            <td>{{ d.i.commentary }}</td>
        </tr>
        {% endif %}

        {% if d.i.notes %}
        <tr>
            <th>Notes</th>
            <td>{{ d.i.notes }}</td>
        </tr>
        {% endif %}

        {% if d.show_ru_data and d.ru and d.ru.ru_notes %}
        <tr>
            <th>Заметки</th>
            <td>{{ d.ru.ru_notes }}</td>
        </tr>
        {% endif %}

        {% if d.show_sbs_data and d.sbs and d.sbs.sbs_notes %}
        <tr>
            <th>SBS Notes</th>
            <td>{{ d.sbs.sbs_notes }}</td>
        </tr>
        {% endif %}

        {% if d.show_ru_data and d.ru and d.ru.ru_cognate %}
