{{ d.header }}
<body>
<div class="dpd">
    <p>
        {% if d.sbs and d.sbs.class_anki %}
        <a class="link" href="{{ d.sbs_class_link }}">
            <i>(cl.{{ d.sbs.class_anki }}{{ '*' if d.sbs.class_extra else '' }})</i>
        </a>
        <span class="gray"> | </span>
        {% endif %}

        {{ d.i.pos }}. 
        {% if d.i.plus_case %}
        ({{ d.i.plus_case }}) 
        {% endif %}

        {% if d.su and d.su.tbw %}
        <a class="link" href="{{ d.su.tbw }}">{{ d.meaning_combo_html }}</a>
        {% else %}
        {{ d.meaning_combo_html }}
        {% endif %}

        {% if d.i.construction_summary %}
        [{{ d.i.construction_summary }}] 
        {% endif %}

        {{ d.i.degree_of_completion_html }} 
        {% if d.show_id %}
        <span class="gray">{{ d.i.id }}</span>
        {% endif %}
    </p>
</div>
<div class="button-box">
    {% if d.i.needs_audio_button %}
    <a class="dpd-button play" onclick="sbs_playAudio('{{ d.i.lemma_clean }}', this)" title="Play Audio"><svg viewBox="0 0 24 24" width="16px" height="16px" fill="currentColor" stroke="currentColor" stroke-width="0"><path d="M8 5v14l11-7z"></path></svg></a>
    {% endif %}
    {% if d.i.needs_sutta_info_button %}
    <a class="dpd-button" href="#" data-target="sutta_info_{{ d.i.lemma_1_ }}">sutta</a>
    {% endif %}
    {% if d.i.needs_grammar_button or d.show_grammar %}
    <a class="dpd-button" href="#" data-target="grammar_{{ d.i.lemma_1_ }}">grammar</a>
    {% endif %}
    {% if d.needs_sbs_example_button %}
    <a class="dpd-button" href="#" data-target="sbs_example_{{ d.i.lemma_1_ }}">sbs</a>
    {% endif %}
    {% if d.i.needs_example_button %}
    <a class="dpd-button" href="#" data-target="example_{{ d.i.lemma_1_ }}">example</a>
    {% endif %}
    {% if d.i.needs_examples_button %}
    <a class="dpd-button" href="#" data-target="examples_{{ d.i.lemma_1_ }}">examples</a>
    {% endif %}
    {% if d.i.needs_conjugation_button %}
    <a class="dpd-button" href="#" data-target="conjugation_{{ d.i.lemma_1_ }}">conjugation</a>
    {% endif %}
    {% if d.i.needs_declension_button %}
    <a class="dpd-button" href="#" data-target="declension_{{ d.i.lemma_1_ }}">declension</a>
    {% endif %}
    {% if d.i.needs_root_family_button %}
    <a class="dpd-button" href="#" data-target="family_root_{{ d.i.lemma_1_ }}">root family</a>
    {% endif %}
    {% if d.i.needs_word_family_button %}
    <a class="dpd-button" href="#" data-target="family_word_{{ d.i.lemma_1_ }}">word family</a>
    {% endif %}
    {% if d.i.needs_compound_family_button %}
    <a class="dpd-button" href="#" data-target="family_compound_{{ d.i.lemma_1_ }}">compound family</a>
    {% elif d.i.needs_compound_families_button %}
    <a class="dpd-button" href="#" data-target="family_compound_{{ d.i.lemma_1_ }}">compound families</a>
    {% endif %}
    {% if d.i.needs_idioms_button %}
    <a class="dpd-button" href="#" data-target="family_idiom_{{ d.i.lemma_1_ }}">idioms</a>
    {% endif %}
    {% if d.i.needs_set_button %}
    <a class="dpd-button" href="#" data-target="family_set_{{ d.i.lemma_1_ }}">set</a>
    {% elif d.i.needs_sets_button %}
    <a class="dpd-button" href="#" data-target="family_set_{{ d.i.lemma_1_ }}">sets</a>
    {% endif %}
    {% if d.i.needs_frequency_button %}
    <a class="dpd-button" href="#" data-target="frequency_{{ d.i.lemma_1_ }}">frequency</a>
    {% endif %}
    <a class="dpd-button" href="#" data-target="feedback_{{ d.i.lemma_1_ }}">feedback</a>
</div>

{% if d.i.needs_sutta_info_button %}
