{% if d.i.needs_grammar_button or d.show_grammar %}
<div id="grammar_{{ d.i.lemma_1_ }}" class="dpd content hidden">
    <table class="grammar">
        <tr>
            <th>Lemma</th>
            <td>{{ d.i.lemma_clean }}</td>
        </tr>

        {% if d.i.lemma_trad_clean != d.i.lemma_clean %}
        <tr>
            <th>Traditional Lemma</th>
            <td>{{ d.i.lemma_trad_clean }}</td>
        </tr>
        {% endif %}

        <tr>
            <th>IPA</th>
            <td>
                /{{ d.i.lemma_ipa }}/
                {% if d.i.audio_male1 %}
                <a class="dpd-button play small" onclick="sbs_playAudio('{{ d.i.lemma_clean }}', this, 'male1')" data-title="male1">
                    <svg viewBox="0 0 24 24">
                        <path d="M8 5v14l11-7z"></path>
                    </svg>
                </a>
                {% endif %}
                {% if d.i.audio_male2 %}
