    const familyRootHtml = sbs_makeFamilyRootHtml(data, fr, "lemma");
    const familyRootElement = document.getElementById(
      `family_root_${lemmaTag}`
    );
    if (familyRootElement) familyRootElement.innerHTML = familyRootHtml;
