  audio.addEventListener("error", function () {
    if (buttonElement) {
      // Change icon to cross
      buttonElement.innerHTML = `
                <svg viewBox="0 0 24 24" width="16px" height="16px" fill="currentColor" stroke="currentColor" stroke-width="2">
