    if (data.family_root != ""
        && typeof ru_family_root_json !== "undefined"
    ) {
        const fr = ru_family_root_json[data.family_root];
        const familyRootHtml = ru_makeFamilyRootHtml(fr, data, "lemma");
        const familyRootElement = document.getElementById(`ru_family_root_${lemmaTag}`);
        if (familyRootElement) familyRootElement.innerHTML = familyRootHtml;
    };

    //// family idioms

    if (
        data.family_idioms
        && data.family_idioms.length > 0
        && typeof ru_family_idiom_json !== "undefined"
    ) {
        const familyIdiomHtml = ru_makeFamilyIdioms(data)
        const familyIdiomElement = document.getElementById(`ru_family_idiom_${lemmaTag}`)
        if (familyIdiomElement) familyIdiomElement.innerHTML = familyIdiomHtml
    };

    //// family sets

    if (
        data.family_sets
        && data.family_sets.length > 0
        && typeof ru_family_set_json !== "undefined"
    ) {
        const familySetHtml = ru_makeFamilySets(data)
        const familySetElement = document.getElementById(`ru_family_set_${lemmaTag}`)
        if (familySetElement) familySetElement.innerHTML = familySetHtml
    };

    //// family word

    if (
        data.family_word
